import operator

def solve(tokens):
    """Evaluate Reverse Polish Notation tokens using operator module.
    Division truncates toward zero as per problem statement.
    """
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': lambda a, b: int(a / b),  # trunc toward zero
    }
    stack = []
    for t in tokens:
        if t in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[t](a, b))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

